            { "/s shuts down, /f forces programs to close, /t 30 waits 30 seconds first. During that wait you can still cancel it from a command prompt with  shutdown /a . Every shutdown RPMac starts is written to shutdown.log next to the CSV, so you can see why it happened.", "/s apaga, /f fuerza el cierre de programas, /t 30 espera 30 segundos antes. Durante esa espera aún puedes cancelarlo desde un símbolo del sistema con  shutdown /a . Cada apagado que inicia RPMac se registra en shutdown.log junto al CSV, para que veas por qué ocurrió." },
            { "A curve needs at least two points.", "Una curva necesita al menos dos puntos." },
            { "A dying fan can cook the machine long before any one sensor hits the limit above. This only counts a fan as stalled when it is being asked to spin faster than {0} RPM and reads below it anyway, for {1} seconds — so a fan that is idle on purpose never triggers it.", "Un ventilador que falla puede sobrecalentar el equipo mucho antes de que un sensor llegue al límite de arriba. Un ventilador solo cuenta como bloqueado si se le pide girar a más de {0} RPM y aun así lee menos durante {1} segundos — así, un ventilador parado a propósito nunca lo activa." },
