            { " fans", " ανεμιστήρες" },
            { " isn't reading a temperature right now.", " δεν μετράει θερμοκρασία αυτή τη στιγμή." },
            { " sensors", " αισθητήρες" },
            { " · hottest: ", " · θερμότερος: " },
            { " · updated ", " · ενημερώθηκε " },
            { "(no presets yet)", "(δεν υπάρχουν ακόμη προφίλ)" },
            { ". Run  shutdown /a  to cancel.", ". Εκτελέστε  shutdown /a  για ακύρωση." },
            { "/s shuts down, /f forces programs to close, /t 30 waits 30 seconds first. During that wait you can still cancel it from a command prompt with  shutdown /a . Every shutdown RPMac starts is written to shutdown.log next to the CSV, so you can see why it happened.", "Το /s τερματίζει, το /f κλείνει αναγκαστικά τα προγράμματα, το /t 30 περιμένει πρώτα 30 δευτερόλεπτα. Στο διάστημα αυτό μπορείτε ακόμη να ακυρώσετε από τη γραμμή εντολών με  shutdown /a . Κάθε τερματισμός που ξεκινά το RPMac καταγράφεται στο shutdown.log δίπλα στο CSV, ώστε να βλέπετε γιατί έγινε." },
            { "A curve needs at least two points.", "Μια καμπύλη χρειάζεται τουλάχιστον δύο σημεία." },
            { "A dying fan can cook the machine long before any one sensor hits the limit above. This only counts a fan as stalled when it is being asked to spin faster than {0} RPM and reads below it anyway, for {1} seconds — so a fan that is idle on purpose never triggers it.", "Ένας ανεμιστήρας που χαλάει μπορεί να υπερθερμάνει το μηχάνημα πολύ πριν κάποιος αισθητήρας φτάσει το παραπάνω όριο. Ένας ανεμιστήρας θεωρείται κολλημένος μόνο αν του ζητείται να γυρίζει πάνω από {0} RPM και παρ' όλα αυτά δείχνει λιγότερο για {1} δευτερόλεπτα — έτσι ένας σκόπιμα σταματημένος ανεμιστήρας δεν το ενεργοποιεί ποτέ." },
            { "Active", "Ενεργό" },
            { "Add", "Προσθήκη" },
            { "Added ", "Προστέθηκε: " },
            { "All good", "Όλα εντάξει" },
            { "All sensors (raw)", "Όλοι οι αισθητήρες (ακατέργαστοι)" },
            { "Also shut down if a fan stalls", "Τερματισμός και αν σταματήσει ανεμιστήρας" },
            { "Alternatively set the fans to “Max”.", "Εναλλακτικά, ρυθμίστε τους ανεμιστήρες σε «Μέγ.»." },
            { "Ambient", "Περιβάλλον" },
            { "Ambient 2", "Περιβάλλον 2" },
            { "App Icon", "Εικονίδιο εφαρμογής" },
            { "Append every reading to history.csv, so you can look back at what ran hot during a game or a long render.", "Προσθήκη κάθε μέτρησης στο history.csv, ώστε να δείτε αργότερα τι ζεστάθηκε σε ένα παιχνίδι ή σε μια μεγάλη απόδοση." },
            { "Apple Mac detected, SMC valid{0}. Control enabled.", "Εντοπίστηκε Mac της Apple, έγκυρο SMC{0}. Ο έλεγχος ενεργοποιήθηκε." },
            { "AppleT2Smc.bin is missing next to MacBreeze.exe.", "Λείπει το AppleT2Smc.bin δίπλα στο MacBreeze.exe." },
