            { "Automatically opens the app at sign-in.", "Ανοίγει την εφαρμογή αυτόματα κατά τη σύνδεση – ως διαχειριστής, χωρίς ερώτηση UAC." },
            { "Based on {0} by golirino (github.com/golirt1/RPMAC). Like {0}, MacBreeze is licensed under the GNU GPL 2.0: you may use, change and share it freely as long as the source code and this notice stay with it. Includes InpOut32 and the PawnIO module for T2 Macs (licenses: see LICENSE and NOTICE).", "Βασίζεται στο {0} του golirino (github.com/golirt1/RPMAC). Όπως το {0}, το MacBreeze διατίθεται με άδεια GNU GPL 2.0: μπορείτε να το χρησιμοποιείτε, να το τροποποιείτε και να το μοιράζεστε ελεύθερα, εφόσον συνοδεύεται από τον πηγαίο κώδικα και αυτή τη σημείωση. Περιλαμβάνει το InpOut32 και τη μονάδα PawnIO για Mac με T2 (άδειες: δείτε LICENSE και NOTICE)." },
