            { "Biggest consumer: {0} with {1:0} % CPU. For sustained load a fan curve is worth it.", "Μεγαλύτερος καταναλωτής: {0} με {1:0} % CPU. Για παρατεταμένο φορτίο αξίζει μια καμπύλη ανεμιστήρα." },
