            { "Choose the interface language.", "Επιλέξτε τη γλώσσα του περιβάλλοντος." },
            { "Choose what the tray icon displays — the app icon, nothing, or a live temperature.", "Επιλέξτε τι δείχνει το εικονίδιο δίπλα στο ρολόι — το εικονίδιο της εφαρμογής, τίποτα ή μια ζωντανή θερμοκρασία." },
            { "Click “Fix automatically” below (installs PawnIO 2.0.1 unrestricted + test signing), then restart.", "Κάντε κλικ παρακάτω στο «Αυτόματη επιδιόρθωση» (εγκαθιστά PawnIO 2.0.1 unrestricted + δοκιμαστική υπογραφή) και μετά κάντε επανεκκίνηση." },
            { "Colors, shapes and gauges of MacBreeze. The app restarts briefly when you switch.", "Χρώματα, σχήματα και δείκτες του MacBreeze. Η εφαρμογή επανεκκινείται για λίγο κατά την αλλαγή." },
