            { "For a machine nobody is watching. If the hottest sensor stays at {0} or above for {1} seconds — with the fans already at maximum — Windows is told to shut down cleanly instead of waiting for the CPU to cut power on its own.", "Για ένα μηχάνημα που δεν το παρακολουθεί κανείς. Αν ο θερμότερος αισθητήρας μείνει στους {0} ή παραπάνω για {1} δευτερόλεπτα — με τους ανεμιστήρες ήδη στο μέγιστο — τα Windows τερματίζονται σωστά, αντί να περιμένουν τη CPU να κόψει μόνη της το ρεύμα." },
