            { "Give the sensor a name first.", "Δώστε πρώτα όνομα στον αισθητήρα." },
            { "Hard drive", "Σκληρός δίσκος" },
            { "High overall load ({0:0} % CPU), spread across many programs. Setting the fans to “Max” or using a curve helps.", "Υψηλό συνολικό φορτίο ({0:0} % CPU), μοιρασμένο σε πολλά προγράμματα. Βοηθά η ρύθμιση των ανεμιστήρων σε «Μέγ.» ή μια καμπύλη." },
            { "Highest Temp", "Μέγιστη θερμ." },
            { "Highest temp (any sensor)", "Μέγιστη θερμοκρασία (οποιοσδήποτε αισθητήρας)" },
