            { "Ignore tiny temperature wobbles and ease the fan down slowly, so a curve doesn't make it audibly hunt up and down.", "Αγνόηση μικρών διακυμάνσεων θερμοκρασίας και σταδιακή μείωση του ανεμιστήρα, ώστε μια καμπύλη να μην τον ανεβοκατεβάζει ακουστά." },
