            { "On T2 Macs (2018–2020) this is expected until PawnIO is set up: the T2 chip blocks direct SMC access, MacBreeze reaches it through PawnIO (unrestricted).", "Σε Mac με T2 (2018–2020) αυτό είναι φυσιολογικό μέχρι να ρυθμιστεί το PawnIO: το τσιπ T2 μπλοκάρει την άμεση πρόσβαση στο SMC, και το MacBreeze το φτάνει μέσω PawnIO (unrestricted)." },
            { "On older Macs the SMC is usually stuck; a restart fixes it.", "Σε παλαιότερα Mac το SMC συνήθως έχει κολλήσει· μια επανεκκίνηση το διορθώνει." },
