            { "PawnIO is not installed or not loaded (CreateFile error {0}). T2 Macs need the UNRESTRICTED edition of PawnIO (2.0.1 or 2.3.0+); the regular installer from pawnio.eu does not load the MacBreeze module.", "Το PawnIO δεν είναι εγκατεστημένο ή φορτωμένο (σφάλμα CreateFile {0}). Τα Mac με T2 χρειάζονται την έκδοση UNRESTRICTED του PawnIO (2.0.1 ή 2.3.0+)· το κανονικό πρόγραμμα εγκατάστασης από το pawnio.eu δεν φορτώνει τη μονάδα του MacBreeze." },
            { "PawnIO refused access (CreateFile error 5). Start MacBreeze as administrator.", "Το PawnIO αρνήθηκε την πρόσβαση (σφάλμα CreateFile 5). Εκτελέστε το MacBreeze ως διαχειριστής." },
            { "Plug in the charger. High fan speeds drain extra battery.", "Συνδέστε τον φορτιστή. Οι υψηλές στροφές ανεμιστήρων καταναλώνουν επιπλέον μπαταρία." },
